def inner(ctx, policy_file_path: Optional[Path], target: Path, output:
    ScanOutput, console: Console=main_console, *args, **kwargs):
    from safety.scan.main import scan
    from safety.scan.util import get_safety_version

    try:
        # Perform the actual scan
        scan_result = scan(target=target, output=output, console=console, ctx=ctx, *args, **kwargs)
        return scan_result
    except Exception as e:
        # Handle exceptions appropriately
        if hasattr(ctx.obj, 'console'):
            ctx.obj.console.print(f"Error during scan: {e}")
        raise
